const crypto = require('crypto');
const input = $input.first().json;
const payload = input.body;
const headers = input.headers || {};
const timestamp = String(headers['x-automation-timestamp'] || '');
const signature = String(headers['x-automation-signature'] || '');
if (!payload || typeof payload !== 'object' || !/^\d{10}$/.test(timestamp)) throw new Error('Invalid signed notification');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Expired notification');
const expectedKeys = ['estado', 'evento', 'fecha', 'moneda', 'pedido_id', 'total'];
if (Object.keys(payload).sort().join('|') !== expectedKeys.sort().join('|')) throw new Error('Unexpected notification fields');
if (payload.evento !== 'pago' || !['aprobado', 'rechazado'].includes(payload.estado) || payload.moneda !== 'COP' || !/^\d+$/.test(String(payload.total)) || !/^\d+$/.test(String(payload.pedido_id)) || !Number.isFinite(Date.parse(payload.fecha))) throw new Error('Invalid payment event');
        const expected = crypto.createHmac('sha256', $env.N8N_W1_SECRET).update(`${timestamp}.${JSON.stringify(payload)}`).digest('hex');
const receivedBuffer = Buffer.from(signature, 'hex');
const expectedBuffer = Buffer.from(expected, 'hex');
if (receivedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(receivedBuffer, expectedBuffer)) throw new Error('Invalid notification signature');
const centavos = BigInt(payload.total);
const totalPesos = `${(centavos / 100n).toLocaleString('es-CO')},${String(centavos % 100n).padStart(2, '0')}`;
return [{ json: { ...payload, total_pesos: totalPesos } }];

